head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > M > setHolidayRef]<br/>팝업 달력에 휴일로 표시할 날짜를 DataCollection 으로 설정합니다.",
    "validation" : [        
        "renderType=component 인 경우에 휴일이 팝업 달력에 표시됩니다.",
        "ref(필수) 파라미터로 접근 가능한 DataCollection 의 컬럼을 'data:[DataCollection ID].[Key 또는 Column ID]' 형식으로 설정합니다.",
        "날짜 데이터는 'yyyyMMdd' 포맷으로 정의되어야 하며 '*MMdd' 포맷으로 정의 시 매해 같은 날짜가 휴일로 표시됩니다.",
        "휴일로 설정된 날짜는 빨간색으로 표시됩니다.",
        "설정값이 형식에 맞지 않거나 접근할 수 없는 DataCollection 이면 적용되지 않습니다.",
        "DataCollection 의 데이터가 변경되면 InputCalendar 에 즉시 반영됩니다.",
        "설정된 휴일 정보를 삭제하려면 DataCollection 의 데이터를 삭제해야 합니다.",
        "setHolidayRef() 메소드로 휴일 정보가 설정되면 setHoliday() 메소드로 설정된 휴일 정보는 무시됩니다.",
    ]
}


scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onclick"]);

    // comp 생성 함수 호출
    $c.gcm.createBasicInputCalendar(eList);
}



scwin.btn_setHolidayRef_onclick = function (e) {
	target1.setHolidayRef(par_ref.getText());
};



scwin.btn_getHoliday_onclick = function (e) {
    setTimeout(() => {
        let targetElement = document.querySelector('div[id*="target1_calendar"]');
        let arrHolidays = [];

        if (targetElement) {            
            let holidays = targetElement.querySelectorAll('td[class*="w2calendar_holiday"]')

            for (var i=0; i < holidays.length; i++) {
                arrHolidays.push(holidays[i].textContent);
            }
        }
        else {
            wf_body_bottom.getObj("scwin").setReturnValue("팝업 달력을 한번 오픈해야 정보 가져올 수 있음");
        }    

        wf_body_bottom.getObj("scwin").setReturnValue('휴일 : ' + arrHolidays);

    }, 100);
}



scwin.target1_onclick = function (e) {
    scwin.btn_getHoliday_onclick();
}



scwin.btn_removeAll_onclick = function (e) {
	dlt_holiday_ref.removeAll();
};



scwin.btn_setHoliday_onclick = function (e) {
	target1.setHoliday("20251101");
};
